<?php $isEdit=!empty($doctor);?><div class="panel form-panel"><form method="post" action="<?= $isEdit?url('/doctors/'.$doctor['id'].'/update'):url('/doctors') ?>" class="form-grid"><?= csrf_field() ?><div class="field"><label>Nombre completo *</label><input name="name" value="<?= e(old('name',$doctor['name']??'')) ?>" required></div><div class="field"><label>Especialidad *</label><select name="specialty_id" required><option value="">Seleccionar</option><?php foreach($specialties as $s):?><option value="<?= $s['id'] ?>" <?= (int)old('specialty_id',$doctor['specialty_id']??0)===(int)$s['id']?'selected':'' ?>><?= e($s['name']) ?></option><?php endforeach;?></select></div><div class="field"><label>No. colegiado</label><input name="license_no" value="<?= e(old('license_no',$doctor['license_no']??'')) ?>"></div><div class="field"><label>Teléfono</label><input name="phone" value="<?= e(old('phone',$doctor['phone']??'')) ?>"></div><div class="field field-full"><label>Correo</label><input type="email" name="email" value="<?= e(old('email',$doctor['email']??'')) ?>"><?php if(error('email')):?><small class="error-text"><?= e(error('email')) ?></small><?php endif;?></div><label class="switch-row field-full"><input type="checkbox" name="active" <?= (int)old('active',$doctor['active']??1)===1?'checked':'' ?>><span>Médico activo</span></label><div class="form-actions field-full"><a class="btn" href="<?= url('/doctors') ?>">Cancelar</a><button class="btn btn-primary">Guardar</button></div></form></div>
